package com.ecoaccess.console; import java.time.*;import java.util.*;
public class ConsoleInput {private final Scanner s=new Scanner(System.in); public String text(String p){System.out.print(p);return s.nextLine().trim();} public int number(String p){while(true)try{return Integer.parseInt(text(p));}catch(NumberFormatException e){System.out.println("Invalid input. Please enter a valid number.");}} public LocalDate date(String p){while(true)try{return LocalDate.parse(text(p));}catch(Exception e){System.out.println("Use date format YYYY-MM-DD.");}} public LocalTime time(String p){while(true)try{return LocalTime.parse(text(p));}catch(Exception e){System.out.println("Use time format HH:MM.");}} public void pause(){text("Press Enter to continue...");}}
